import{_ as a,o as r,c as t,a2 as p}from"./chunks/framework.DfDAiEgj.js";const d=JSON.parse('{"title":"知识产权","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/IPR.md","filePath":"ai-dive/IPR.md","lastUpdated":null}'),h={name:"ai-dive/IPR.md"};function o(n,e,i,l,s,c){return r(),t("div",null,[...e[0]||(e[0]=[p('<h1 id="知识产权" tabindex="-1">知识产权 <a class="header-anchor" href="#知识产权" aria-label="Permalink to &quot;知识产权&quot;">​</a></h1><p>发展产权、技术、信息等生产要素市场</p><p>产权市场是指进行产权交易的市场。要依法保护各类产权，健全产权交易规则和监管制度，推动产权有序流转，保障所有市场主体的平等地位和发展权利。进一步发展技术、信息市场。引入竞争机制，保护知识产权，实行技术成果有偿转让，实现技术产品和信息商品化、产业化。<a href="https://www.zhihu.com/pub/reader/120204365/chapter/1396810420301160448" target="_blank" rel="noreferrer">4</a></p><p><a href="http://ip.people.com.cn/" target="_blank" rel="noreferrer">http://ip.people.com.cn/</a></p><p>中国知识产权法律制度：<a href="https://www.zhihu.com/pub/book/120051492" target="_blank" rel="noreferrer">https://www.zhihu.com/pub/book/120051492</a></p><hr><p><a href="https://www.zhuanzhi.ai/topic/2001037522103010" target="_blank" rel="noreferrer">https://www.zhuanzhi.ai/topic/2001037522103010</a></p><p><a href="https://news.51cto.com/art/202108/680050.htm" target="_blank" rel="noreferrer">https://news.51cto.com/art/202108/680050.htm</a></p><p><a href="https://picture.iczhiku.com/weixin/message1619158957697.html" target="_blank" rel="noreferrer">https://picture.iczhiku.com/weixin/message1619158957697.html</a></p><p>嘉宾简介：王鼎盛（ Ding Sheng Ong ），马来亚大学计算机系学士，在微众银行人工智能首席科学家范力欣博士和马来亚大学陈志胜教授两位导师的指导下学习。研究兴趣包括深度学习、计算机视觉和对抗学习，目前的研究重点是对抗学习、人工智能知识产权保护。</p><p>分享摘要：随着工业界对深度学习模型的使用越来越广泛，机器学习即服务（MLaas）逐渐兴起，也利用了这些模型创造了可观的收入。由于这些深度学习模型可以轻松地被未经授权的第三方抄袭与剽窃，深度学习模型的知识产权 （IPR）保护也因此成了各公司会专注的问题。虽然目前已有用于卷积神经网络（CNN）的 IPR 保护方法，但是却不能直接使用在生成对抗网络（GANs）——另一种被广泛用于生成逼真图像的深度学习模型。因此，本文提出了一种<strong>基于黑盒与白盒的 GAN 模型 IPR 保护方法</strong>。实验结果表明，本方法并不会损害 GAN 本来的性能（如图像生成、图像超分辨率以及样式转换）。本方法也能够抵御去除嵌入的水印（removal）和模糊（ambiguity）攻击。本次分享将会解说如何基于黑盒与白盒的方式保护对抗生成网络（GANs），以及如何抵御各种水印攻击。</p><p>论文地址：<a href="https://arxiv.org/abs/2102.04362" target="_blank" rel="noreferrer">https://arxiv.org/abs/2102.04362</a></p><p>项目地址：<a href="https://github.com/dingsheng-ong/ipr-gan" target="_blank" rel="noreferrer">https://github.com/dingsheng-ong/ipr-gan</a></p><hr><h2 id="论文" tabindex="-1">论文 <a class="header-anchor" href="#论文" aria-label="Permalink to &quot;论文&quot;">​</a></h2><p>知识产权(IP)指的是对思想创造的保护，它既有道德价值，也有商业价值。知识产权在法律框架下以专利、版权和商标等形式受到保护，使发明者能够从他们的发明中获得认可或经济利益。</p><hr><h2 id="版权" tabindex="-1">版权 <a class="header-anchor" href="#版权" aria-label="Permalink to &quot;版权&quot;">​</a></h2><p>版权旨在保护原创作品，如小说、计算机程序、戏剧、音乐、电影、照片和绘画等。通常，版权法旨在激励为了公众利益而创作原创作品。要获得版权保护，作者作品必须由作者创造，且必须在创作作品时作出一定程度的独立努力。如果您是原创作品的作者，那么您通常拥有该作品的版权。<a href="https://sellercentral.amazon.sg/gp/help/external/JLSFCSEA8C9EZYZ?language=zh_CN&amp;ref=efph_JLSFCSEA8C9EZYZ_cont_G201361070" target="_blank" rel="noreferrer">2</a></p><hr><h2 id="智能体作品的知识产权归属" tabindex="-1">智能体作品的知识产权归属 <a class="header-anchor" href="#智能体作品的知识产权归属" aria-label="Permalink to &quot;智能体作品的知识产权归属&quot;">​</a></h2><p>人工智能可以自动迭代算法并反馈学习，产生新数据，具备一定的创造能力。结合算法的设计，专用人工智能虽已可以产出一定的创作性成果，但模仿型的创作不具备主观创作能力。知识所属权是指权利人对其智力劳动所创作的成果和经营活动中的标记、信誉依法享有的专有权利。[11]由于人工智能不具备法律主体资格，无法行使权力并承担义务与责任，因此人工智能体对创作物不具备相应的著作权等相关权利。</p><p>代表性的案例是欧洲专利局（EPO）于2019年12月底，以申请案不符合欧洲专利公约（EPC）为理由，正式做出驳回AI智能DABUS的两项发明申请案（EP 18275163、EP 18275174）的决定。但是，随着高级人工智能不断向独立智能体发展，其本身的地位和行为属性，使得人和物的关系需要重新界定，知识产权的归属问题在未来也会成为新的治理焦点。<a href="http://www.xml-data.cn/KXYSH/html/328afb24-eb80-483c-b267-dfd1a61144bb.htm" target="_blank" rel="noreferrer">3</a></p><p>TODO:以人工智能为基础的新科技革命对知识产权制度的挑战与机遇 <a href="https://doc.paperpass.com/journal/20180032kxdshdyx.html?origin=2" target="_blank" rel="noreferrer">https://doc.paperpass.com/journal/20180032kxdshdyx.html?origin=2</a></p>',24)])])}const f=a(h,[["render",o]]);export{d as __pageData,f as default};
